"""Generate the game's model spec from the approved export's measured metadata."""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent


def write_spec(info):
    target = HERE.parents[2]/'src/presentation/assets/hearth-spirit.ts'
    target.write_text(
        '// Generated by art/spirits/hearth/runtime_spec.py. Re-export to change timing.\n'
        'import type { ModelSpec } from "../models.ts"\n'
        'import hearthSpiritUrl from "../../../art/spirits/hearth/hearth-animated.glb?url"\n\n'
        f'export const hearthSpiritModel = {{ url: hearthSpiritUrl, height: {info["height_m"]:.8f}, '
        f'clips: {json.dumps(info["clips"])} }} as const satisfies ModelSpec\n')


if __name__ == '__main__':
    write_spec(json.loads((HERE/'animation.json').read_text()))
